// Normalise both triggers to { user_id, source }.
//  - Schedule trigger  -> user_id = null  -> batch over all recently-active users.
//  - Supabase DB webhook on INSERT into mobile_checkins -> body.record carries the
//    new check-in row, including app_user_id (production users.id).
// A webhook call WITHOUT a resolvable user id is dropped (never fall through to a
// full batch run from a malformed webhook).
const results = [];
for (const item of $input.all()) {
  const j = item.json ?? {};
  const isWebhook = j.body !== undefined || j.headers !== undefined;
  const rec = (j.body && (j.body.record ?? j.body)) || {};
  const id = Number(rec.app_user_id ?? rec.user_id ?? NaN);
  if (Number.isInteger(id) && id > 0) {
    results.push({ json: { user_id: id, source: 'checkin' } });
  } else if (!isWebhook) {
    results.push({ json: { user_id: null, source: 'daily' } });
  }
  // webhook with no user id -> skip silently
}
return results;

