// Hallucination guard + shaping for the insert.
// Drop any snippet_id the model invented (must be in this user's candidate pool),
// cap at 5, and pre-escape the reasons JSON for safe SQL inlining.
const results = [];
for (const item of $input.all()) {
  const src = $('Gather user signals + candidates').itemMatching(item.index)?.json ?? {};
  const allowed = new Set((src.candidates ?? []).map((c) => Number(c.snippet_id)));
  const out = item.json.output ?? item.json;
  const picks = (out.recommendations ?? [])
    .map((r) => ({ snippet_id: Number(r.snippet_id), reason: String(r.reason ?? '').slice(0, 500) }))
    .filter((r) => Number.isInteger(r.snippet_id) && allowed.has(r.snippet_id))
    .slice(0, 5);
  const userId = Number(src.user_id);
  if (!picks.length || !Number.isInteger(userId)) continue;
  results.push({
    json: {
      user_id: userId,
      source: String(src.source ?? 'daily'),
      // validated integers only -> safe to inline into SQL
      id_list: picks.map((p) => p.snippet_id).join(','),
      // single quotes doubled -> safe inside a SQL string literal
      picks_sql: JSON.stringify(picks).replace(/'/g, "''"),
      picks,
    },
  });
}
return results;
